    """

    @staticmethod
    def string_to_int(value):
        """
        Convert a string to an integer.

        :param value: The string to convert.
        :return: The integer value.
        :raises ValueError: If the string cannot be converted to an integer.
        """
        try:
            return int(value)
        except ValueError as e:
            raise ValueError(f"Cannot convert {value} to an integer.") from e

    @staticmethod
    def string_to_float(value):
        """
        Convert a string to a float.

        :param value: The string to convert.
        :return: The float value.
        :raises ValueError: If the string cannot be converted to a float.
        """
        try:
            return float(value)
        except ValueError as e:
            raise ValueError(f"Cannot convert {value} to a float.") from e

    @staticmethod
    def string_to_bool(value):
        """
        Convert a string to a boolean.

        :param value: The string to convert.
        :return: The boolean value.
        :raises ValueError: If the string cannot be converted to a boolean.
        """
        value = value.lower()
        if value in ('true', '1', 't', 'y', 'yes'):
            return True
        elif value in ('false', '0', 'f', 'n', 'no'):
            return False
        else:
            raise ValueError(f"Cannot convert {value} to a boolean.")

    @staticmethod
    def string_to_list(value, delimiter=','):
        """
        Convert a string to a list of strings.

        :param value: The string to convert.
        :param delimiter: The delimiter used to split the string.
        :return: The list of strings.
        """
        return [item.strip() for item in value.split(delimiter)]

    @staticmethod
    def string_to_dict(value, pair_delimiter=',', key_value_delimiter=':'):
        """
        Convert a string to a dictionary.

        :param value: The string to convert.
        :param pair_delimiter: The delimiter used to split key-value pairs.
        :param key_value_delimiter: The delimiter used to split keys and values.
        :return: The dictionary.
        :raises ValueError: If the string cannot be converted to a dictionary.
        """
        try:
            return dict(item.split(key_value_delimiter, 1) for item in value.split(pair_delimiter))
        except ValueError as e:
            raise ValueError(f"Cannot convert {value} to a dictionary.") from e

