# data.py

def recursive_diff(d1, d2, log=False):
    """
    Recursively compares two dictionaries and logs the differences if log is True.

    :param d1: First dictionary to compare.
    :param d2: Second dictionary to compare.
    :param log: Boolean flag to enable logging of differences.
    :return: A dictionary containing the differences.
    """
    diff = {}

    # Check for keys in d1 that are not in d2
    for key in d1:
        if key not in d2:
            diff[key] = {'old': d1[key], 'new': None}
            if log:
                print(f"Key '{key}' is missing in the second dictionary.")
        else:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_diff = recursive_diff(d1[key], d2[key], log=log)
                if sub_diff:
                    diff[key] = sub_diff
            elif d1[key] != d2[key]:
                diff[key] = {'old': d1[key], 'new': d2[key]}
                if log:
                    print(f"Key '{key}' has different values: {d1[key]} != {d2[key]}")

    # Check for keys in d2 that are not in d1
    for key in d2:
        if key not in d1:
            diff[key] = {'old': None, 'new': d2[key]}
            if log:
                print(f"Key '{key}' is missing in the first dictionary.")

    return diff
```

