class Command(ScrapyCommand):

    requires_project = False
    default_settings = {'LOG_ENABLED': False}

    def syntax(self):
        return "<spider_name> <domain>"

    def short_desc(self):
        return "Generate new spider using pre-defined templates"

    def long_desc(self):
        return "Generate new spider using pre-defined templates located in scrapy/templates/spiders. " \
               "You can list available templates using the command:\n\n" \
               "    scrapy genspider --list\n\n" \
               "You can also create your own templates in _spider_templates directory under your project"

    def add_options(self, parser):
        ScrapyCommand.add_options(self, parser)
        parser.add_option("-t", "--template", dest="template", default='basic',
                          help="Use a custom template. Available templates:\n" + "\n".join(self._list_templates()))
        parser.add_option("--force", dest="force", action="store_true", default=False,
                          help="If the spider already exists, overwrite it with the template")

    def run(self, args, opts):
        if len(args) not in (1, 2):
            raise UsageError()

        if len(args) == 1:
            # If only one argument is provided, consider it as the domain
            domain = args[0]
            spider_name = domain.split('.')[0]
        else:
            spider_name, domain = args

        if not is_valid_url(domain):
            raise UsageError(f"Invalid domain: {domain}")

        domain = normalize_url(domain)
        spidercls = to_unicode(re.sub(r'[^a-zA-Z0-9_]+', '_', spider_name))
        if not spidercls[0].islower():
            raise UsageError(f"Spider name must start with a lowercase letter: {spider_name}")

        if not re.match(r'^[a-z]+[a-z0-9_]*$', spidercls):
            raise UsageError(f"Spider name must contain only lowercase letters, digits, and underscores: {spider_name}")

        if not opts.template:
            print(f"No template specified, using 'basic' as default")
            opts.template = 'basic'

        if not self._is_valid_template(opts.template):
            raise UsageError(f"Unknown template: {opts.template}")

        if not opts.force and self._spider_exists(spidercls):
            raise UsageError(f"Spider {spidercls} already exists in project, use --force to overwrite")

        self._genspider(spidercls, domain, opts.template)

    def _genspider(self, spidercls, domain, template):
        template_file = self._find_template(template)
        spider_file = f"{spidercls}.py"
        spider_module = f"{self.settings.get('BOT_NAME')}.spiders.{spidercls}"
        with open(template_file, 'r') as f:
            template_content = f.read()
        rendered_content = render_templatefile(template_content, {
            'project_name': self.settings.get('BOT_NAME'),
            'spider_name': spidercls,
            'domain': domain,
            'scrapy_version': __version__,
        })
        with open(spider_file, 'w') as f:
            f.write(rendered_content)
        print(f"Created spider {spidercls} using template {template}")

    def _is_valid_template(self, template):
        return template in self._list_templates()

    def _list_templates(self):
        template_dir = self._get_template_dir()
        return [os.path.splitext(os.path.basename(f))[0] for f in os.listdir(template_dir) if f.endswith('.tmpl')]

    def _get_template_dir(self):
        return os.path.join(os.path.dirname(__file__), '..', 'templates', 'spiders')

    def _spider_exists(self, spidercls):
        spider_file = f"{spidercls}.py"
        return os.path.exists(spider_file)
